use super::*;

/// The fullest single-token label for a centre frequency across every band this surface now knows —
/// the 802.11 channel AND/OR the BLE channel, since 2.4 GHz carries both: `ch6`, `ch1·BLE4`,
/// `BLE37·adv`, or a raw `2402MHz` when it lands on no grid we can name.
pub fn band_label(freq_mhz: u32) -> String {
    match (channel_for(freq_mhz), ble_channel_for(freq_mhz)) {
        (Some(w), Some(b)) => format!("ch{w}·BLE{b}"),
        (Some(w), None) => format!("ch{w}"),
        (None, Some(b)) if is_ble_advertising(freq_mhz) => format!("BLE{b}·adv"),
        (None, Some(b)) => format!("BLE{b}"),
        (None, None) => format!("{freq_mhz}MHz"),
    }
}
